fn matmul(A: LayoutTensor[...], B: LayoutTensor[...], C: LayoutTensor[...]):
    let row = global_idx.y
    let col = global_idx.x
    if row < M and col < N:
        var acc: Float32 = 0.0
        for k in range(K):
            acc += Float32(A[row, k]) * Float32(B[k, col])
        C[row, col] = BFloat16(acc)
